window.docContents[175].resolve({"/5___-Representations-of-finite-groups___-Further-results/5___1___-Frobenius-Schur-indicator/Introduction-to-the-Frobenius-Schur-indicator/#Chapter5___Introduction":{"contents":"Suppose that G is a finite group and V is an irreducible representation of G over \\mathbb{C}.\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.1. Frobenius-Schur indicator\tIntroduction to the Frobenius-Schur indicator","header":"Introduction to the Frobenius-Schur indicator","id":"/5___-Representations-of-finite-groups___-Further-results/5___1___-Frobenius-Schur-indicator/Introduction-to-the-Frobenius-Schur-indicator/#Chapter5___Introduction"},"/2___-Basic-notions-of-representation-theory/2___2___-Algebras/Homomorphism-of-algebras/#Chapter2___Definition2___2___6":{"contents":"Definition 2.2.6. A homomorphism of algebras f : A \\to B is a linear map such that f(xy) = f(x)f(y) for all x, y \\in A and f(1) = 1.\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.2. Algebras\tHomomorphism of algebras","header":"Homomorphism of algebras","id":"/2___-Basic-notions-of-representation-theory/2___2___-Algebras/Homomorphism-of-algebras/#Chapter2___Definition2___2___6"},"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Subrepresentation-of-a-quiver-representation/#Chapter2___Definition2___8___8":{"contents":"Definition 2.8.8. A subrepresentation of a representation (V_i, x_h) of a quiver Q is a representation (W_i, x'_h) where W_i \\subseteq V_i for all i \\in I and where x_h(W_{h'}) \\subseteq W_{h''} and x'_h = x_h|_{W_{h'}} : W_{h'} \\longrightarrow W_{h''} for all h \\in E.\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.8. Quivers\tSubrepresentation of a quiver representation","header":"Subrepresentation of a quiver representation","id":"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Subrepresentation-of-a-quiver-representation/#Chapter2___Definition2___8___8"},"/7___-Introduction-to-categories/7___8___-Complexes-and-cohomology/Split-exact-sequence/#Chapter7___Example7___8___3":{"contents":"Example 7.8.3. The sequence 0 \\to X \\to X \\oplus Z \\to Z \\to 0 with the obvious morphisms is a short exact sequence. Such a sequence is called split. It corresponds to the trivial extension of Z by X.\n\n\n\n","context":"Introduction to Representation Theory\t7. Introduction to categories\t7.8. Complexes and cohomology\tSplit exact sequence","header":"Split exact sequence","id":"/7___-Introduction-to-categories/7___8___-Complexes-and-cohomology/Split-exact-sequence/#Chapter7___Example7___8___3"}});
